<?php
/** In-plugin read-only documentation for TaxoCommerce Images. */
defined( 'ABSPATH' ) || exit;
final class TaxoCommerce_Images_Manual {
    public static function sections() {
        return array(
            array('id' => "usuario",'title' => "Manual de usuario",'level' => "h1",'description' => "Guía para el administrador de WordPress. La pestaña Manual es de solo lectura: no ejecuta escaneos ni modifica imágenes."),
            array('id' => "inventario",'title' => "1. Inventario",'level' => "h2",'description' => "Los indicadores muestran páginas, entradas, categorías y productos sin imagen asignada, formatos locales (JPEG, PNG, WebP, AVIF) y anomalías conocidas del último escaneo. Optimizar originales y miniaturas ejecuta una recomprensión sobre archivos; Convertir JPG/PNG a WebP transforma archivos y puede modificar referencias. Realiza una copia de seguridad antes de iniciar cualquiera de los dos. Los paneles permiten pausar, reanudar y detener los trabajos. Los recuentos de anomalías dependen del último informe, no de un escaneo automático al abrir la página."),
            array('id' => "anomalias",'title' => "2. Anomalías",'level' => "h2",'description' => "Iniciar auditoría inspecciona la biblioteca de Media, los originales, ALT, dimensiones, peso, archivos ausentes y miniaturas. Guardar velocidad ajusta de 1 (suave) a 5 (máxima) el tamaño de próximos lotes, sin reiniciar el cursor. Continuar siguiente lote (manual) intenta procesar otro tramo. Reiniciar desde cero descarta el avance anterior para volver a auditar; Borrar informe elimina los resultados guardados de la auditoría, no las imágenes. Los resultados se agrupan por tipo de incidencia y el enlace Revisar abre la imagen en Media local. El procesamiento usa WP-Cron en el servidor cuando está operativo."),
            array('id' => "asignacion",'title' => "3. Asignación",'level' => "h2",'description' => "Separa páginas, entradas, categorías y productos que no tienen imagen asignada. Asignar esta imagen aplica un candidato relacionado por categoría; Buscar en Media abre el selector nativo; Asignar desde Media utiliza la imagen elegida; Subir y asignar incorpora un archivo local y lo asigna al elemento. Asignar automáticamente todo el grupo recorre sus elementos pendientes, sin sobrescribir imágenes existentes. Continuar y Pausar permiten gestionar su progreso; los paneles del servidor también permiten Reanudar y Detener. Guardar prioridad configura la carga 1–5 para cada grupo. Los productos solo pueden recibir automáticamente una imagen válida de su propia galería, nunca la de otro producto. No se descargan imágenes remotas de proveedores."),
            array('id' => "sinuso",'title' => "4. Sin uso y duplicadas",'level' => "h2",'description' => "Escanear toda la biblioteca ejecuta el análisis completo de uso y duplicados. Continuar análisis completo, Pausar, Reanudar y Detener gestionan el proceso. Guardar prioridad ajusta el trabajo 1–5. Los filtros separan sin uso conocido, duplicadas, usadas, casos para revisión y todas; Revisar en Media abre la biblioteca. Una duplicación exacta se identifica por SHA-256 del archivo original. «Sin uso conocido» no acredita que pueda borrarse: pueden existir referencias no detectadas. Este informe no elimina ni consolida automáticamente imágenes."),
            array('id' => "etiquetas",'title' => "5. Etiquetas y atributos",'level' => "h2",'description' => "Escanear toda la biblioteca busca ALT ausente, ALT de imágenes decorativas, títulos deficientes, dimensiones sin registrar y archivos ausentes. Guardar prioridad regula la velocidad de los lotes; Continuar análisis completo y los controles de pausa/reanudación administran el trabajo. En cada fila se puede editar Título y ALT, marcar Decorativa: ALT vacío y pulsar Guardar. No genera títulos ni textos ALT genéricos automáticamente. Solo marca decorativa cuando el administrador lo decide."),
            array('id' => "media",'title' => "6. Media local",'level' => "h2",'description' => "Buscar localiza adjuntos de imagen y la paginación recorre la biblioteca. Metadatos abre el editor de la imagen; Media abre la ficha nativa de WordPress. Guardar metadatos actualiza título visible, ALT, leyenda y descripción sin renombrar el fichero físico. Regenerar miniaturas reconstruye tamaños; Reducir a límites configurados puede modificar el fichero, conservando una copia local cuando corresponde; Restaurar original aparece únicamente si existe un backup local válido. Verifica los archivos y prepara un backup antes de transformar imágenes."),
            array('id' => "miniaturas",'title' => "7. Miniaturas",'level' => "h2",'description' => "Muestra cada tamaño registrado por WordPress o el tema (ancho, alto y recorte). La columna «No generar en nuevas subidas» permite excluir tamaños futuros; Guardar tamaños desactivados aplica la política. No elimina miniaturas que ya existen. Desactivar tamaños utilizados por el tema o WooCommerce puede perjudicar el diseño; comprueba primero su uso."),
            array('id' => "ajustes",'title' => "8. Ajustes",'level' => "h2",'description' => "Configura ancho máximo, alto máximo, peso recomendado y calidad de compresión. Guardar ajustes conserva los valores. Las casillas de Nuevas subidas y Calidad automática aplican los límites y la calidad cuando WordPress procesa archivos nuevos; los cambios no recomprimen automáticamente el catálogo ya existente. Las optimizaciones manuales se ejecutan desde Inventario o el editor de Media."),
            array('id' => "autotest",'title' => "9. Auto Test",'level' => "h2",'description' => "Ejecutar Auto Test realiza 17 verificaciones independientes del funcionamiento del plugin. El informe distingue correcto, error y no aplicable/no ejecutado. Es un diagnóstico de solo lectura; no modifica archivos, metadatos, catálogo ni trabajos en cola. Un test correcto no sustituye las pruebas de escritura ni una auditoría completa."),
            array('id' => "servidor",'title' => "10. Procesos y recuperación",'level' => "h2",'description' => "Los procesos de auditoría, asignación, etiquetas, duplicados, optimización y WebP usan trabajos persistentes con WP-Cron. Pueden continuar después de cerrar el navegador si el cron de WordPress se ejecuta. En sitios sin tráfico conviene configurar una tarea cron real del hosting que invoque wp-cron.php. Pausar servidor interrumpe próximos lotes; Reanudar continúa desde el cursor; Detener cancela la continuación. La CPU indicada corresponde a la petición PHP, no a la CPU global del servidor. Comienza con prioridad 3 y ajusta según tiempos y memoria observados."),
            array('id' => "desarrollador",'title' => "Manual técnico para desarrolladores",'level' => "h1",'description' => "Documentación de mantenimiento para ampliar Images sin romper la equivalencia funcional existente."),
            array('id' => "arquitectura",'title' => "11. Arquitectura y módulos",'level' => "h2",'description' => "Punto de entrada: taxocommerce-images/taxocommerce-images.php. Inicializa TaxoCommerce_Images, Inventory, Assignment, Audit, Maintenance, Load, Background, Actions, Auto_Test y Thumbnails. Las rutinas de optimización y WebP se conservan en legacy-optimizer-engine.php y legacy-webp-engine.php; existen módulos legacy de auditoría de referencias y AJAX. La pestaña Manual es una clase separada de solo lectura. Media/attachments de WordPress es la fuente canónica, sin índice propio de proveedor ni tablas nuevas para imágenes. Funciona sin Core; cuando Core está activo registra un submenú."),
            array('id' => "rutas",'title' => "12. Rutas, permisos y entradas",'level' => "h2",'description' => "La navegación usa wp-admin/admin.php?page=taxocommerce-images&tab=summary|audit|assignment|references|labels|library|thumbnails|settings|auto-test|manual. Las acciones con escritura utilizan admin-post.php (por ejemplo taxocommerce_images_save_metadata, taxocommerce_images_assign_one, taxocommerce_images_assign_media, taxocommerce_images_assign_upload, taxocommerce_images_save_settings y taxocommerce_images_save_thumbnail_policy). Los trabajos usan wp_ajax_taxocommerce_images_background_control, wp_ajax_taxocommerce_images_maintenance y los hooks del auditor. Comprobar manage_options (o el filtro taxocommerce_images_manage_capability), upload_files y edit_post cuando corresponda, junto con nonces y sanitización de parámetros. Mantener compatibilidad de slugs y hooks al evolucionar."),
            array('id' => "datos",'title' => "13. Datos, estado y rendimiento",'level' => "h2",'description' => "Los attachments y sus metadatos viven en las tablas nativas wp_posts/wp_postmeta, usando el prefijo real de WordPress. Las configuraciones y estados de proceso residen en opciones como taxocommerce_images_settings, taxocommerce_images_work_priority y taxocommerce_images_bg_{mode}; los resultados de etiquetas y referencias también se registran en metadatos de attachments. TaxoCommerce_Images_Background emplea el hook taxocommerce_images_background_tick: selecciona procesos, aplica bloqueos, conserva cursor/actor/estado y reprograma lotes con WP-Cron. TaxoCommerce_Images_Load adapta tamaño y retardo al tiempo, memoria y CPU de la petición, no del servidor completo. Evitar que procesos simultáneos escriban la misma imagen; respetar bloqueos de mutación."),
            array('id' => "integraciones",'title' => "14. Transformación y seguridad",'level' => "h2",'description' => "La asignación utiliza relaciones de categorías y APIs nativas de Media; nunca asigna automáticamente imágenes de otro producto. La optimización modifica originales y miniaturas; WebP convierte JPG/PNG y puede actualizar URLs conocidas; comprueba dependencias de GD/Imagick, miniaturas, permisos del sistema de archivos y espacio libre. El backup local de una imagen no equivale a un backup integral del sitio. La detección de duplicados usa hash SHA-256 exacto y los hallazgos son candidatos a revisión, no licencia para borrar. No se permiten borrados masivos automáticos de imágenes «sin uso» basados únicamente en el informe."),
            array('id' => "pruebas",'title' => "15. Evolución y pruebas",'level' => "h2",'description' => "Antes de cambiar una función, inventariar pestañas, botones, rutas, efectos y casos límite; preservar las capacidades existentes. Actualizar ambos manuales y sus pruebas en la misma PR. Ejecutar php -l sobre todos los archivos, tests/audit-load-smoke.php, tests/auto-test-smoke.php y tests/functional-contract.php en WordPress aislado, además del smoke de asignación, node --check para JavaScript y WordPress Plugin Check. Workflows: .github/workflows/images-contract-check.yml y images-standalone-check.yml. Validar realmente en STAGING la UI móvil, WP-Cron, filtros, permisos y transformaciones sobre archivos de prueba con backup antes de promover a producción. PHP mínimo 7.4 y WordPress 6.5 según cabecera del plugin."),
        );
    }
    public static function render() {
        if ( ! current_user_can( (string) apply_filters( 'taxocommerce_images_manage_capability', 'manage_options' ) ) ) {
            wp_die( esc_html__( 'No tienes permisos para consultar este manual.', 'taxocommerce-images' ) );
        }
        $sections = self::sections();
        echo '<section class="tci-manual" aria-label="Manual de TaxoCommerce Images">';
        echo '<style>.tci-manual{max-width:1180px;margin:20px 0}.tci-manual h1{font-size:26px;line-height:1.3;margin:30px 0 14px}.tci-manual h2{font-size:21px;line-height:1.4;margin:0 0 12px}.tci-manual h3{font-size:16px;margin:14px 0 8px}.tci-manual p,.tci-manual li{font-size:14px;line-height:1.7}.tci-manual-index,.tci-manual-card{background:#fff;border:1px solid #dcdcde;border-radius:5px;padding:20px;margin:16px 0}.tci-manual-index a{display:inline-block;margin:6px 12px 6px 0}.tci-manual-card{scroll-margin-top:35px}.tci-manual-index{overflow-wrap:anywhere}@media(max-width:782px){.tci-manual-index,.tci-manual-card{padding:14px}.tci-manual h1{font-size:23px}.tci-manual h2{font-size:19px}}</style>';
        echo '<h1>Manual de TaxoCommerce Images</h1>';
        echo '<p>Documentación integrada para administradores y desarrolladores. Consultarla no modifica imágenes ni inicia procesos.</p>';
        echo '<nav class="tci-manual-index" aria-label="Índice del manual"><strong>Contenido</strong><div>';
        foreach ( $sections as $section ) {
            echo '<a href="#' . esc_attr( $section['id'] ) . '">' . esc_html( $section['title'] ) . '</a>';
        }
        echo '</div></nav>';
        $technical = false;
        foreach ( $sections as $section ) {
            if ( 'h1' === $section['level'] ) {
                if ( 'desarrollador' === $section['id'] ) { $technical = true; }
                echo '<h1 id="' . esc_attr( $section['id'] ) . '">' . esc_html( $section['title'] ) . '</h1>';
            } else {
                echo '<section class="tci-manual-card" id="' . esc_attr( $section['id'] ) . '"><h2>' . esc_html( $section['title'] ) . '</h2>';
                echo '<h3>' . esc_html( $technical ? 'Implementación, dependencias y mantenimiento' : 'Funciones, botones y precauciones' ) . '</h3>';
                echo '<p>' . esc_html( $section['description'] ) . '</p></section>';
            }
        }
        echo '</section>';
    }
}
